//! Browser bindings for the Rust `resrap-rs` implementation.
//!
//! The Svelte site imports these functions through the package generated by
//! `wasm-pack`. Keeping the surface small makes the JavaScript wrapper simple.

use resrap_rs::{Resrap, templates};
use serde_json::json;
use wasm_bindgen::prelude::*;

/// Generates from an arbitrary ABNF grammar.
#[wasm_bindgen]
pub fn generate_text(grammar: &str, startpoint: &str, seed: f64, tokenlen: usize) -> String {
    if tokenlen == 0 {
        return "Error: tokenlen must be greater than zero".to_string();
    }

    let mut resrap = Resrap::new();
    if let Err(err) = resrap.parse_grammar("sample", grammar) {
        return format!("Error: {err}");
    }

    resrap.generate_complete_with_seeded("sample", startpoint, seed as u64, tokenlen)
}

/// Generates from one of the embedded templates.
#[wasm_bindgen]
pub fn generate_template(template: &str, startpoint: &str, seed: f64, tokenlen: usize) -> String {
    if tokenlen == 0 {
        return "Error: tokenlen must be greater than zero".to_string();
    }

    let mut resrap = Resrap::new();
    if let Err(err) = templates::load(&mut resrap, template) {
        return format!("Error: {err}");
    }

    resrap.generate_complete_with_seeded(template, startpoint, seed as u64, tokenlen)
}

/// Returns the embedded template metadata as JSON. The Svelte page parses the
/// result directly and uses `grammar` for the preview.
#[wasm_bindgen]
pub fn get_templates() -> String {
    let list = templates::list()
        .into_iter()
        .map(|template| {
            json!({
                "name": template.name,
                "language": template.language,
                "description": template.description,
                "grammar": template.grammar,
            })
        })
        .collect::<Vec<_>>();

    serde_json::to_string(&list).unwrap_or_else(|_| "[]".to_string())
}
